const input = $('When chat message received').first().json.chatInput ?? '';
const output = $json.output ?? '';

const id = $execution.id.replace(/-/g, '').padEnd(32, '0');

const traceId = id.substring(0, 32);
const spanId = id.substring(0, 16);

const end = Date.now() * 1000000;
const start = end - 5000000000;

return {
  json: {
    resourceSpans: [
      {
        resource: {
          attributes: [
            {
              key: 'service.name',
              value: {
                stringValue: 'MIRA-n8n'
              }
            }
          ]
        },
        scopeSpans: [
          {
            scope: {
              name: 'n8n.mira'
            },
            spans: [
              {
                traceId: traceId,
                spanId: spanId,
                name: 'MIRA Project Request',
                kind: 1,
                startTimeUnixNano: String(start),
                endTimeUnixNano: String(end),
                attributes: [
                  {
                    key: 'langfuse.trace.name',
                    value: {
                      stringValue: 'MIRA Project Request'
                    }
                  },
                  {
                    key: 'langfuse.observation.type',
                    value: {
                      stringValue: 'chain'
                    }
                  },
                  {
                    key: 'langfuse.observation.input',
                    value: {
                      stringValue: JSON.stringify(input)
                    }
                  },
                  {
                    key: 'langfuse.observation.output',
                    value: {
                      stringValue: JSON.stringify(output)
                    }
                  }
                ]
              }
            ]
          }
        ]
      }
    ]
  }
};
